   string output=Environment.GetEnvironmentVariable("SPATIAL_NATIVE_ARTWORK_OUTPUT");if(string.IsNullOrEmpty(output))throw new InvalidOperationException("explicit-native-artwork-output-required");Directory.CreateDirectory(output);var receipts=new JArray();
   foreach(var artwork in ArtworkCatalog.Builtins.Where(a=>Guids.ContainsKey(a.Id))){
    var scene=EditorSceneManager.OpenScene(artwork.ScenePath,OpenSceneMode.Single);var roots=scene.GetRootGameObjects();var content=roots.SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).Single(t=>t.name=="SceneModel");var projection=roots.SelectMany(r=>r.GetComponentsInChildren<WindowProjection>(true)).Single();var library=UnityEngine.Resources.Load<NativeSceneLibrary>(NativeSceneLibrary.ResourcePath(artwork.Id));if(!library)throw new InvalidDataException("native-export-library-missing:"+artwork.Id);library.Require(library.Digest);var metadata=(JObject)library.Manifest["scenes"].Single(s=>(string)s["id"]==artwork.Id);var resources=new JArray();var definitions=new JArray();var soundMap=new Dictionary<UnityEngine.Object,string>();
