    AudioClip Clip(string name){var candidates=soundMap.Keys.Cast<AudioClip>().Where(c=>c.name==name).ToArray();if(candidates.Length!=1)throw new InvalidDataException("native-export-sound:"+artwork.Id+":"+name);return candidates[0];}
