      for(int i=0;i<targets.Length;i++){string name=(string)targets[i]["name"];var target=content.GetComponentsInChildren<Transform>(true).Single(t=>t.name==name);var trail=content.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Trail_"+name);script.targets[i]=target.gameObject;script.trails[i]=trail.gameObject;nodes.Add(target);nodes.Add(trail);var c=targets[i]["center"];script.centers[i]=new Vector3((float)c[0],(float)c[1],(float)c[2])*scale;script.radii[i]=(float)targets[i]["radius"]*scale;script.keys[i]="minishot.v1.target-"+(i+1).ToString("D2");}
      script.music=Clip("aurora");script.hitSound=Clip("Hit");script.resetSound=Clip("Reset");
