     var compiled=CilboxProgramCompiler.CompileForNativeBridge(temp);var type=author.GetType();JToken Value(Type t,object value){if(value==null)return JValue.CreateNull();if(t.IsArray)return new JArray(((Array)value).Cast<object>().Select(v=>Value(t.GetElementType(),v)));if(value is AudioClip clip)return new JValue(soundMap[clip]);if(value is GameObject go)return new JValue(nodes.IndexOf(go.transform));if(value is Vector3 vector)return Vector(vector);return JToken.FromObject(value);}
     var fields=new JObject();foreach(JObject field in (JArray)compiled.Program["classes"].Single(c=>(string)c["id"]==compiled.ClassId(type))["fields"]){var native=type.GetFields(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).Single(f=>compiled.FieldId(type,f.Name)==(string)field["id"]);fields[(string)field["id"]]=Value(native.FieldType,native.GetValue(author));}
