     var scriptContent=new JObject{{"frame",new JArray(projection.displayWidth,projection.displayHeight,projection.contentDepth)},{"nodes",contentNodes},{"prefabs",new JArray()},{"resources",definitions}};byte[] bytes=NativeScriptDefinition.Encode(compiled.Program,scriptContent);var manifest=new JObject{{"format","spatial-native-wallpaper"},{"schema",5},{"sdk",SceneCommandCatalog.TargetSdk},{"command_abi",SceneCommandCatalog.Abi},{"catalog_digest",SceneCommandCatalog.Digest},{"work_id",Guids[artwork.Id]},{"revision","0.4.0-preview.1"},{"name",artwork.Name},{"scene",new JObject{{"id",artwork.Id},{"source_sha256",metadata["source_sha256"]},{"library_digest",library.Digest}}},{"node_paths",new JArray(nodes.Select(t=>PathFrom(content,t)))},{"resources",resources},{"license",new JObject{{"mode","local-validation"},{"records",new JArray(new JObject{{"name","Original "+artwork.Id},{"source","Retained original scene and original music sources; see source-provenance.json/audio-imports.json"},{"license","Original rights retained; public redistribution unverified"},{"redistribution","unverified"},{"attribution","Original creators; no permission to publicly redistribute inferred"}})}}},{"files",new JObject{{"script.json",new JObject{{"size",bytes.Length},{"sha256",PackageValidator.Digest(bytes)}}}}}};manifest["build_id"]=PackageValidator.Identity(manifest);string destination=System.IO.Path.Combine(output,artwork.Id+".spatial");if(File.Exists(destination))throw new IOException("native-export-refuse-overwrite");using(var zip=new ZipArchive(File.Create(destination),ZipArchiveMode.Create)){using(var stream=zip.CreateEntry("manifest.json").Open()){var data=Encoding.UTF8.GetBytes(manifest.ToString(Newtonsoft.Json.Formatting.None));stream.Write(data,0,data.Length);}using(var stream=zip.CreateEntry("script.json").Open())stream.Write(bytes,0,bytes.Length);}var admitted=NativePackage.Validate(destination);admitted.RequireTrustedScene(library.Digest,(string)metadata["source_sha256"]);File.WriteAllText(System.IO.Path.Combine(output,artwork.Id+".manifest.json"),manifest.ToString());receipts.Add(new JObject{{"file",destination},{"work_id",admitted.WorkId},{"build_id",admitted.BuildId},{"sha256",PackageValidator.Digest(File.ReadAllBytes(destination))},{"native_resources",metadata["assets"].Count()},{"audio_layers",artwork.Id=="rainycafe"?2:1},{"script_nodes",nodes.Count}});
    }finally{UnityEngine.Object.DestroyImmediate(temp);}
   }
   File.WriteAllText(System.IO.Path.Combine(output,"native-artworks.json"),new JObject{{"sdk",SceneCommandCatalog.TargetSdk},{"schema",5},{"command_abi",SceneCommandCatalog.Abi},{"packages",receipts},{"quality","Original trusted scenes, native render assets and original AudioClips; no schema4 payload conversion"},{"manual_pending",new JArray("visual fidelity","real sound","MiniShot pointer and persistence experience","physical multi display")}}.ToString());
  }
 }
